fn extract_token(headers: &HeaderMap, query: Option<&AuthQuery>) -> Option<String> {
    if let Some(auth_header) = headers.get("authorization").and_then(|h| h.to_str().ok()) {
        if let Some(token) = auth_header.strip_prefix("Bearer ") {
            return Some(token.trim().to_string());
        }
    }
    query.and_then(|q| q.token.clone())
}

async fn health_check() -> Json<HealthResponse> {
    Json(HealthResponse {
        status: "ok",
        version: "0.1.0",
    })
}

async fn pair_exchange(
    State(state): State<Arc<RemoteGatewayState>>,
    Json(payload): Json<PairExchangeRequest>,
) -> Result<Json<PairExchangeResponse>, (StatusCode, String)> {
    let (token, device) = state
        .auth_manager
        .exchange_pairing_code(&payload.code, &payload.device_name)
        .map_err(|e| match e {
            AuthError::InvalidPairingCode => (StatusCode::BAD_REQUEST, "Invalid pairing code".into()),
            AuthError::ExpiredPairingCode => (StatusCode::UNAUTHORIZED, "Pairing code expired".into()),
            _ => (StatusCode::UNAUTHORIZED, "Unauthorized".into()),
        })?;

    Ok(Json(PairExchangeResponse { token, device }))
}

/// Resolve `(workspace_id, worktree_label)` for a terminal session from the worktree
/// path that owns it. Degrades gracefully: unmatched paths yield a best-effort label
/// derived from the path itself, missing paths yield `None`.
fn derive_session_metadata(
    registry: &crate::worktree::WorkspaceRegistry,
    worktree_path: Option<&Path>,
) -> (Option<String>, Option<String>) {
    let Some(path) = worktree_path else {
        return (None, None);
    };
    let canonical = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    for (ws_id, mgr) in registry.list() {
        let root = std::fs::canonicalize(mgr.repo_root())
            .unwrap_or_else(|_| mgr.repo_root().to_path_buf());
        if !canonical.starts_with(&root) {
            continue;
        }
        let label = mgr
            .list_worktrees()
            .unwrap_or_default()
            .into_iter()
            .find(|wt| {
                wt.path == path
                    || std::fs::canonicalize(&wt.path)
                        .map(|c| c == canonical)
                        .unwrap_or(false)
            })
            .and_then(|wt| {
                wt.branch_short_name()
                    .map(str::to_string)
                    .or_else(|| wt.path.file_name().map(|f| f.to_string_lossy().into_owned()))
            })
            .or_else(|| path.file_name().map(|f| f.to_string_lossy().into_owned()));
        return (Some(ws_id), label);
    }
    (
        None,
        path.file_name().map(|f| f.to_string_lossy().into_owned()),
    )
}

