use ferryx_lib::browser::{BrowserManager, RestoreBrowserRequest};

#[test]
fn browser_manager_restores_the_persisted_browser_identity() {
    let manager = BrowserManager::new();
    let restored = manager
        .restore_session(RestoreBrowserRequest {
            browser_id: "persisted-browser-42".into(),
            url: "https://example.com/docs".into(),
            visible: Some(false),
        })
        .expect("restore browser");

    assert_eq!(restored.browser_id, "persisted-browser-42");
    assert_eq!(restored.webview_label, "browser-persisted-browser-42");
    assert_eq!(restored.url, "https://example.com/docs");
    assert!(!restored.visible);

    let again = manager
        .restore_session(RestoreBrowserRequest {
            browser_id: "persisted-browser-42".into(),
            url: "https://different.example".into(),
            visible: Some(true),
        })
        .expect("idempotent restore");
    assert_eq!(again.browser_id, restored.browser_id);
    assert_eq!(again.url, restored.url);
}

